CREATE TABLE IF NOT EXISTS appointment_price_adjustment (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, appointment_id BINARY(16) NOT NULL, price_currency VARCHAR(3) NOT NULL, price_unscaled BIGINT NOT NULL, price_scale INT NOT NULL, reason VARCHAR(2048) NULL, CONSTRAINT fk_appointment_price_adjustment_appointment_id__id FOREIGN KEY (appointment_id) REFERENCES appointment(id) ON DELETE CASCADE ON UPDATE RESTRICT);
ALTER TABLE appointment_price_adjustment ADD CONSTRAINT appointment_price_adjustment_appointment_id_unique UNIQUE (appointment_id);
CREATE TABLE IF NOT EXISTS appointment_price_adjustment_services (id BINARY(16) PRIMARY KEY, createdAt TIMESTAMP(6) NOT NULL, updatedAt TIMESTAMP(6) NULL, price_adjustment_id BINARY(16) NOT NULL, service_id BINARY(16) NOT NULL, service_name VARCHAR(1024) NOT NULL, service_group_id BINARY(16) NOT NULL, price_currency VARCHAR(3) NOT NULL, price_unscaled BIGINT NOT NULL, price_scale INT NOT NULL, duration_minutes BIGINT NOT NULL, CONSTRAINT fk_appointment_price_adjustment_services_price_adjustment_id__id FOREIGN KEY (price_adjustment_id) REFERENCES appointment_price_adjustment(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE INDEX appointment_price_adjustment_services_price_adjustment_id ON appointment_price_adjustment_services (price_adjustment_id);
CREATE INDEX appointment_price_adjustment_services_service_id ON appointment_price_adjustment_services (service_id);
